={
  "statement": "MATCH (n) WHERE (n:Album AND toLower(n.title) CONTAINS toLower($name)) OR (n:Artist AND toLower(n.name) CONTAINS toLower($name)) OR (n:Genre AND toLower(n.name) = toLower($name)) OR (n:Label AND toLower(n.name) CONTAINS toLower($name)) MATCH (n)-[r]-(m) WHERE NOT m:Chunk WITH startNode(r) AS s, r, endNode(r) AS e RETURN DISTINCT coalesce(s.title + ' (' + s.year + ')', s.name) AS from, type(r) + coalesce(' [' + r.instrument + ']', '') AS relation, coalesce(e.title + ' (' + e.year + ')', e.name) AS to, coalesce(CASE WHEN s:Album THEN s.mbid END, CASE WHEN e:Album THEN e.mbid END) AS album_mbid ORDER BY relation, from LIMIT 150",
  "parameters": { "name": {{ JSON.stringify(String($json.name ?? $json.query ?? $json.input ?? Object.values($json)[0] ?? '')) }} }
}

