// Graph facts + the MusicBrainz release pages they come from
const d = $input.first().json.data;
const rows = d.values.map(v => Object.fromEntries(d.fields.map((f, i) => [f, v[i]])));
const facts = rows.map(r => `${r.from} -${r.relation}-> ${r.to}`);
const sources = [...new Set(rows.map(r => r.album_mbid).filter(Boolean))]
  .map(id => `https://musicbrainz.org/release/${id}`);
const input = $('When Executed by Another Workflow').first().json;
return [{ json: { result: facts.length
  ? `Graph facts (MusicBrainz):\n${facts.join('\n')}\n\nSources:\n${sources.join('\n')}`
  : `No graph data found for "${input.name ?? JSON.stringify(input)}". Try a single album title or artist name.` } }];
